arguments.command:
python3 -c '
import sys
sys.path.insert(0, "/workspace")
from tools.parse_value_loss import parse

recs = parse(["/workspace/logs/stage_b.log"])
for r in recs:
    if r["kind"] == "rollout":
        if r["label"] == "eval":
            print("EVAL", r["step"], r["metrics"])
        elif r["label"] == "rollout":
            m = r["metrics"]
            print(f"ROLLOUT {r[\"step\"]}: rewards={m.get(\"rollout/rewards\")}, resp_len={m.get(\"rollout/response_lengths\")}, rounds={m.get(\"rollout/round_number\")}, values={m.get(\"rollout/values\")}, adv={m.get(\"rollout/advantages\")}")
        elif r["label"] == "perf":
            m = r["metrics"]
            print(f"PERF {r[\"step\"]}: resp_len_mean={m.get(\"rollout/response_len/mean\")}, trunc={m.get(\"rollout/truncated_ratio\")}")
    elif r["kind"] == "step" and r["role"] == "actor":
        m = r["metrics"]
        print(f"ACTOR STEP {r[\"step\"]}: pg_loss={m.get(\"train/pg_loss\")}, clipfrac={m.get(\"train/pg_clipfrac\")}, ppo_kl={m.get(\"train/ppo_kl\")}, grad_norm={m.get(\"train/grad_norm\")}, entropy={m.get(\"train/entropy_loss\")}")
'

