import ray

from slime.observability.logging_utils import configure_logger, finish_tracking, init_tracking
from slime.ray.placement_group import create_placement_groups, create_rollout_manager, create_training_models
from slime.utils.arguments import parse_args
from slime.utils.misc import should_run_periodic_action


def train(args):
    configure_logger()
    release_train = args.release_train

    # allocate the GPUs
    pgs = create_placement_groups(args)
    init_tracking(args)

    # create the rollout manager, with sglang engines inside.
    # need to initialize rollout manager first to calculate num_rollout
    rollout_manager, num_rollout_per_epoch = create_rollout_manager(args, pgs["rollout"])

    actor_model, critic_model = create_training_models(args, pgs, rollout_manager)

    if args.offload_rollout and not release_train:
        ray.get(rollout_manager.onload_weights.remote())

    # Always push actor weights to rollout once weights are loaded.
    actor_model.update_weights()

    if args.check_weight_update_equal:
        ray.get(rollout_manager.check_weights.remote(action="compare"))

    if args.offload_rollout:
        ray.get(rollout_manager.onload_kv.remote())

    # special case for eval-only
    if args.num_rollout == 0 and args.eval_interval is not None:
        ray.get(rollout_manager.eval.remote(rollout_id=0))

    def offload_train(actor_trains_this_step):
        # Each model auto-offloads after train() when offload_train is set,
        # so we only need clear_memory for the non-offload case.
        if not args.offload_train:
            if not args.use_critic or actor_trains_this_step:
                actor_model.clear_memory()
            else:
                critic_model.clear_memory()

    # train loop.
    for rollout_id in range(args.start_rollout_id, args.num_rollout):
        if args.eval_interval is not None and rollout_id == 0 and not args.skip_eval_before_train:
            ray.get(rollout_manager.eval.remote(rollout_id))

        rollout_data_ref = ray.get(rollout_manager.generate.remote(rollout_id))

        if args.offload_rollout:
            ray.get(rollout_manager.offload.remote())

        if release_train:
            actor_model.create()

        actor_trains = (not args.use_critic) or rollout_id >= args.num_critic_only_steps
        if args.use_critic:
            value_refs = critic_model.async_train(rollout_id, rollout_data_ref)
            if actor_trains:
                ray.get(actor_model.async_train(rollout_id, rollout_data_ref, external_data=value_refs))
            else:
                ray.get(value_refs)
        else:
            ray.get(actor_model.async_train(rollout_id, rollout_data_ref))

        if release_train or should_run_periodic_action(
            rollout_id, args.save_interval, num_rollout_per_epoch, args.num_rollout
        ):
            force_sync = release_train or rollout_id == args.num_rollout - 1
            if actor_trains:
                actor_model.save_model(rollout_id, force_sync=force_sync)
            if args.use_critic:
                critic_model.save_model(rollout_id, force_sync=force_sync)
            if args.rollout_global_dataset:
                ray.get(rollout_manager.save.remote(rollout_id))

        offload_train(actor_trains)
        if args.offload_rollout and not release_train:
            ray.get(rollout_manager.onload_weights.remote())
        actor_model.update_weights()

        if args.offload_rollout:
            ray.get(rollout_manager.onload_kv.remote())

        if should_run_periodic_action(rollout_id, args.eval_interval, num_rollout_per_epoch):
            ray.get(rollout_manager.eval.remote(rollout_id))

    ray.get(rollout_manager.dispose.remote())
    finish_tracking(args)


if __name__ == "__main__":
    args = parse_args()
    train(args)

# Adapt from https://github.com/NVIDIA/Megatron-LM/blob/b1efb3c7126ef7615e8c333432d76e08038e17ff/pretrain_gpt.py
import argparse
import inspect
import re
from contextlib import nullcontext
from typing import Literal

import torch
from megatron.core import tensor_parallel
from megatron.core.models.gpt import GPTModel
from megatron.core.models.gpt.gpt_layer_specs import (
    get_gpt_decoder_block_spec,
    get_gpt_layer_local_spec,
    get_gpt_layer_with_transformer_engine_spec,
)
from megatron.core.transformer.spec_utils import import_module
from megatron.core.transformer.transformer_config import TransformerConfig
from megatron.training.arguments import core_transformer_config_from_args

from slime.utils.misc import load_function

_INDEXER_DIRECT_SUBMODULE_NAMES = frozenset(
    {
        "wq_b",
        "wk",
        "k_norm",
        "weights_proj",
        "index_kpool_compress_ape",
        "index_kpool_compress_gate",
    }
)


def _is_indexer_parameter(name: str) -> bool:
    """Return whether *name* belongs to a DSA indexer.

    The GLM plugin exposes indexer projections directly under
    ``self_attention``. Megatron's upstream DSA implementation instead nests
    them under ``self_attention.core_attention.indexer``. Keep the ownership
    check structural so similarly named non-indexer projections stay trainable.
    """

    parts = name.split(".")
    for index, part in enumerate(parts):
        if part != "self_attention" or index + 1 >= len(parts):
            continue
        attention_parts = parts[index + 1 :]
        if attention_parts[0] in _INDEXER_DIRECT_SUBMODULE_NAMES:
            return True
        if "indexer" in attention_parts[:-1]:
            return True
    return False


# Adapt from https://github.com/volcengine/verl/blob/c3b20575d2bc815fcccd84bddb4c0401fc4b632b/verl/models/llama/megatron/layers/parallel_linear.py#L82
class LinearForLastLayer(torch.nn.Linear):
    # WORKSPACE CHANGE, part of the shared setup: `bias` defaults to False
    # here, where upstream slime v0.3.2 defaults it to True.
    #
    # Upstream cannot load a critic from a HuggingFace checkpoint at all. The
    # HF loader walks every Megatron parameter and asks the model's mapper for
    # a source tensor; `output_layer.weight` is special-cased (a [1, hidden]
    # value head is skipped when the HF tensor is [vocab, hidden]), but
    # `output_layer.bias` has no HF counterpart and no special case, so
    # `qwen_hf_tensor` raises KeyError("Unsupported Megatron parameter
    # 'output_layer.bias'") before training starts. See
    # slime/backends/megatron_utils/hf_to_megatron/{qwen,common}.py.
    #
    # A value head does not need a bias -- it is one scalar of freedom that
    # V(s) can equally express through the backbone -- and dropping it is the
    # smallest change that lets a critic start from HF weights, which is what
    # Stage B does.
    def __init__(
        self,
        input_size: int,
        output_size: int,
        *,
        config: TransformerConfig,
        bias: bool = False,
    ) -> None:
        super().__init__(in_features=input_size, out_features=output_size, bias=bias)
        self.sequence_parallel = config.sequence_parallel
        if self.sequence_parallel:
            self.weight.sequence_parallel = True
            if bias:
                self.bias.sequence_parallel = True

        init_method_std = getattr(config, "init_method_std", None)
        if init_method_std is None:
            init_method_std = 0.02
        self.weight.data.normal_(mean=0.0, std=init_method_std)
        if bias:
            self.bias.data.zero_()

    def forward(
        self,
        input_: torch.Tensor,
        weight: torch.Tensor | None = None,
        runtime_gather_output: bool | None = None,
    ) -> tuple[torch.Tensor, None]:
        logits = super().forward(input_)
        logits = logits.float()
        if self.sequence_parallel:
            logits = tensor_parallel.gather_from_sequence_parallel_region(logits, tensor_parallel_output_grad=False)
        return logits, None


def _get_model_provider_func(
    args: argparse.Namespace,
    role: Literal["actor", "critic"] = "actor",
):
    # Support custom model provider path (similar to --custom-rm-path for reward models)
    if getattr(args, "custom_model_provider_path", None):

        def wrapped_model_provider(
            pre_process: bool = True, post_process: bool = True, vp_stage: int | None = None
        ) -> GPTModel:
            custom_model_provider = load_function(args.custom_model_provider_path)
            # Check if the custom provider supports vp_stage parameter
            has_vp_stage = "vp_stage" in inspect.signature(custom_model_provider).parameters
            if has_vp_stage:
                model = custom_model_provider(pre_process=pre_process, post_process=post_process, vp_stage=vp_stage)
            else:
                model = custom_model_provider(pre_process=pre_process, post_process=post_process)
            # Apply critic output layer if needed
            if post_process and role == "critic":
                model.output_layer = LinearForLastLayer(
                    input_size=model.config.hidden_size, output_size=1, config=model.config
                )
            return model

        return wrapped_model_provider

    def model_provider(pre_process: bool = True, post_process: bool = True, vp_stage: int | None = None) -> GPTModel:
        """Builds the model.

        If you set the use_legacy_models to True, it will return the legacy GPT model and if not the mcore GPT model.

        Args:
            pre_process (bool, optional): Set to true if you need to compute embedings. Defaults to True.
            post_process (bool, optional): Set to true if you need to want to compute output logits/loss. Defaults to True.


        Returns:
            Union[GPTModel, megatron.legacy.model.GPTModel]: The returned model
        """
        use_te = args.transformer_impl == "transformer_engine"

        # Experimental loading arguments from yaml
        config: TransformerConfig = core_transformer_config_from_args(args)
        # Older GLM Megatron forks consumed this flag from TransformerConfig.
        # Preserve that contract for custom specs, while freeze_model_params()
        # below provides the concrete implementation on current Megatron.
        config.freeze_indexer = getattr(args, "freeze_indexer", False)

        if args.spec is not None:
            transformer_layer_spec = import_module(args.spec)
            # Allow the spec to be a function so that user can use customized Megatron easier.
            if callable(transformer_layer_spec):
                result = transformer_layer_spec(args, config, vp_stage)
                # If the result is itself a model provider (callable with pre_process param),
                # delegate model construction to it directly (e.g. glm-omni VL model).
                if callable(result) and "pre_process" in inspect.signature(result).parameters:
                    model = result(pre_process=pre_process, post_process=post_process, vp_stage=vp_stage)
                    if post_process and role == "critic":
                        model.output_layer = LinearForLastLayer(
                            input_size=config.hidden_size, output_size=1, config=config
                        )
                    return model
                transformer_layer_spec = result
        else:
            if args.num_experts:
                # Define the decoder block spec
                kwargs = {
                    "use_transformer_engine": use_te,
                }
                if vp_stage is not None:
                    kwargs["vp_stage"] = vp_stage
                transformer_layer_spec = get_gpt_decoder_block_spec(config, **kwargs)
            else:
                # Define the decoder layer spec
                if use_te:
                    transformer_layer_spec = get_gpt_layer_with_transformer_engine_spec(
                        num_experts=args.num_experts,
                        moe_grouped_gemm=args.moe_grouped_gemm,
                        qk_layernorm=args.qk_layernorm,
                        multi_latent_attention=args.multi_latent_attention,
                        moe_use_legacy_grouped_gemm=args.moe_use_legacy_grouped_gemm,
                    )
                else:
                    transformer_layer_spec = get_gpt_layer_local_spec(
                        num_experts=args.num_experts,
                        moe_grouped_gemm=args.moe_grouped_gemm,
                        qk_layernorm=args.qk_layernorm,
                        multi_latent_attention=args.multi_latent_attention,
                        moe_use_legacy_grouped_gemm=args.moe_use_legacy_grouped_gemm,
                    )

        build_model_context = nullcontext
        build_model_context_args = {}
        if args.fp8_param_gather:
            try:
                from transformer_engine.pytorch import fp8_model_init

                build_model_context = fp8_model_init
                build_model_context_args["enabled"] = True

                # Check if fp8_model_init supports preserve_high_precision_init_val
                if "preserve_high_precision_init_val" in inspect.signature(fp8_model_init).parameters:
                    build_model_context_args["preserve_high_precision_init_val"] = True
            except Exception as e:
                raise RuntimeError(
                    "--fp8-param-gather requires `fp8_model_init` from TransformerEngine, but not found."
                ) from e

        kwargs = {
            "config": config,
            "transformer_layer_spec": transformer_layer_spec,
            "vocab_size": args.padded_vocab_size,
            "max_sequence_length": args.max_position_embeddings,
            "pre_process": pre_process,
            "post_process": post_process,
            "fp16_lm_cross_entropy": args.fp16_lm_cross_entropy,
            "parallel_output": True,
            "share_embeddings_and_output_weights": not args.untie_embeddings_and_output_weights,
            "position_embedding_type": args.position_embedding_type,
            "rotary_percent": args.rotary_percent,
            "rotary_base": args.rotary_base,
            "rope_scaling": args.use_rope_scaling,
        }

        if vp_stage is not None:
            kwargs["vp_stage"] = vp_stage

        if args.mtp_num_layers:
            from megatron.core.models.gpt.gpt_layer_specs import get_gpt_mtp_block_spec

            mtp_kwargs = {
                "use_transformer_engine": use_te,
            }
            if vp_stage is not None:
                mtp_kwargs["vp_stage"] = vp_stage

            mtp_block_spec = get_gpt_mtp_block_spec(config, transformer_layer_spec, **mtp_kwargs)
            kwargs["mtp_block_spec"] = mtp_block_spec

        with build_model_context(**build_model_context_args):
            model = GPTModel(**kwargs)

        if post_process and role == "critic":
            model.output_layer = LinearForLastLayer(input_size=config.hidden_size, output_size=1, config=config)

        return model

    return model_provider


def wrap_model_provider_with_freeze(original_provider, args):
    def wrapped_provider(
        pre_process=True,
        post_process=True,
        **kwargs,
    ):
        sig = inspect.signature(original_provider)
        provider_kwargs = {
            "pre_process": pre_process,
            "post_process": post_process,
        }
        for key in ["vp_stage", "config", "pg_collection"]:
            if key in sig.parameters:
                provider_kwargs[key] = kwargs.get(key, None)

        model = original_provider(**provider_kwargs)
        freeze_model_params(model, args)

        return model

    return wrapped_provider


def get_model_provider_func(args, role="actor"):
    return wrap_model_provider_with_freeze(_get_model_provider_func(args, role), args)


def freeze_model_params(model: GPTModel, args: argparse.Namespace):
    if getattr(args, "only_train_params_name_list", None):
        for name, param in model.named_parameters():
            param.requires_grad = False
            for pattern in args.only_train_params_name_list:
                if re.search(pattern, name):
                    param.requires_grad = True
                    break

    if getattr(args, "freeze_params_name_list", None):
        for name, param in model.named_parameters():
            for pattern in args.freeze_params_name_list:
                if re.search(pattern, name):
                    param.requires_grad = False
                    break

    if getattr(args, "freeze_indexer", False):
        frozen_indexer_params = []
        has_self_attention_params = False
        for name, param in model.named_parameters():
            has_self_attention_params |= "self_attention" in name.split(".")
            if _is_indexer_parameter(name):
                param.requires_grad = False
                frozen_indexer_params.append(name)

        if has_self_attention_params and not frozen_indexer_params:
            raise RuntimeError(
                "--freeze-indexer was requested, but this model chunk has self-attention "
                "parameters and no recognized DSA indexer parameters."
            )

        # Some pipeline stages may legitimately own no indexer weights, so an
        # empty local tuple is not itself an error.
        model._slime_frozen_indexer_param_names = tuple(frozen_indexer_params)

from __future__ import annotations

import functools
import json
from collections.abc import Callable
from pathlib import Path

import torch
import torch.nn.functional as F
from safetensors import safe_open


class SafetensorReader:
    def __init__(self, path: str | Path):
        self.path = Path(path)
        index_path = self.path / "model.safetensors.index.json"
        if index_path.is_file():
            with index_path.open() as index_file:
                self.weight_map = json.load(index_file)["weight_map"]
        else:
            files = sorted(self.path.glob("*.safetensors"))
            if not files:
                raise FileNotFoundError(f"No safetensors checkpoint found in {self.path}")
            self.weight_map = {}
            for file in files:
                with safe_open(file, framework="pt", device="cpu") as tensors:
                    self.weight_map.update(dict.fromkeys(tensors.keys(), file.name))
        self._files = {}

    def __contains__(self, name: str) -> bool:
        return name in self.weight_map

    @functools.lru_cache(maxsize=1)  # noqa: B019 - cache belongs to this reader instance
    def get_tensor(self, name: str) -> torch.Tensor:
        try:
            filename = self.weight_map[name]
        except KeyError as exc:
            raise KeyError(f"HuggingFace checkpoint does not contain {name!r}") from exc
        if filename not in self._files:
            self._files[filename] = safe_open(self.path / filename, framework="pt", device="cpu")
        tensor = self._files[filename].get_tensor(name)
        scale_name = f"{name}_scale_inv"
        if tensor.element_size() == 1 and scale_name in self:
            scale_file = self.weight_map[scale_name]
            if scale_file not in self._files:
                self._files[scale_file] = safe_open(self.path / scale_file, framework="pt", device="cpu")
            scale = self._files[scale_file].get_tensor(scale_name).to(torch.bfloat16)
            rows, columns = tensor.shape
            block_rows, block_columns = scale.shape
            tensor = F.pad(
                tensor.to(torch.bfloat16),
                (0, block_columns * 128 - columns, 0, block_rows * 128 - rows),
            )
            tensor = tensor.view(block_rows, 128, block_columns, 128)
            tensor.mul_(scale[:, None, :, None])
            tensor = tensor.reshape(block_rows * 128, block_columns * 128)[:rows, :columns]
        return tensor


def strip_mcore_wrappers(name: str) -> str:
    while name.startswith("module."):
        name = name.removeprefix("module.")
    return name.removeprefix("language_model.")


def text_config(config):
    return getattr(config, "text_config", config)


def merge_qkv(q: torch.Tensor, k: torch.Tensor, v: torch.Tensor, config) -> torch.Tensor:
    config = text_config(config)
    num_groups = config.num_key_value_heads
    num_heads = config.num_attention_heads
    head_dim = getattr(config, "head_dim", None) or config.hidden_size // num_heads
    trailing_shape = q.shape[1:]
    q = q.reshape(num_groups, num_heads // num_groups * head_dim, *trailing_shape)
    k = k.reshape(num_groups, head_dim, *trailing_shape)
    v = v.reshape(num_groups, head_dim, *trailing_shape)
    return torch.cat((q, k, v), dim=1).reshape(-1, *trailing_shape).contiguous()


def merge_gate_up(gate: torch.Tensor, up: torch.Tensor) -> torch.Tensor:
    return torch.cat((gate, up), dim=0)


def _tensor_parallel_shard(
    name: str,
    tensor: torch.Tensor,
    *,
    parallel_size: int,
    parallel_rank: int,
    partition_dim: int,
    partition_stride: int,
) -> torch.Tensor:
    if parallel_size == 1:
        return tensor

    if "linear_fc1.weight" in name or "linear_fc1.bias" in name:
        gate, up = tensor.chunk(2, dim=partition_dim)
        gate = torch.chunk(gate, parallel_size, dim=partition_dim)[parallel_rank]
        up = torch.chunk(up, parallel_size, dim=partition_dim)[parallel_rank]
        return torch.cat((gate, up), dim=partition_dim).contiguous()

    if "linear_fc2.weight" in name and partition_dim == 0:
        partition_dim = 1

    chunks = torch.chunk(tensor, parallel_size * partition_stride, dim=partition_dim)
    return torch.cat(chunks[parallel_rank::parallel_size], dim=partition_dim).contiguous()


def shard_mcore_tensor(name: str, tensor: torch.Tensor, parameter: torch.Tensor) -> torch.Tensor:
    from megatron.core import mpu

    if (
        not getattr(parameter, "tensor_model_parallel", False)
        or getattr(parameter, "parallel_mode", None) == "duplicated"
    ):
        return tensor

    if ".experts." in name:
        parallel_size = mpu.get_expert_tensor_parallel_world_size()
        parallel_rank = mpu.get_expert_tensor_parallel_rank()
    else:
        parallel_size = mpu.get_tensor_model_parallel_world_size()
        parallel_rank = mpu.get_tensor_model_parallel_rank()

    return _tensor_parallel_shard(
        name,
        tensor,
        parallel_size=parallel_size,
        parallel_rank=parallel_rank,
        partition_dim=parameter.partition_dim,
        partition_stride=parameter.partition_stride,
    )


def _pad_vocab(args, name: str, tensor: torch.Tensor) -> torch.Tensor:
    if not (name.endswith("embedding.word_embeddings.weight") or name.endswith("output_layer.weight")):
        return tensor
    padded_size = getattr(args, "padded_vocab_size", None)
    if padded_size is None or tensor.shape[0] >= padded_size:
        return tensor
    return F.pad(tensor, (0, 0, 0, padded_size - tensor.shape[0]))


def load_model_hf_weights(
    args,
    model,
    path: str | Path,
    config,
    get_hf_tensor: Callable[[str, SafetensorReader, object], torch.Tensor],
) -> None:
    from slime.backends.megatron_utils.update_weight.common import named_params_and_buffers

    reader = SafetensorReader(path)
    with torch.no_grad():
        for name, parameter in named_params_and_buffers(args, model):
            tensor = get_hf_tensor(name, reader, config)
            if name.endswith("output_layer.weight") and parameter.shape[0] == 1 and tensor.shape[0] != 1:
                continue
            tensor = shard_mcore_tensor(name, _pad_vocab(args, name, tensor), parameter)
            if tensor.shape != parameter.shape:
                raise ValueError(
                    f"Shape mismatch loading {name}: HuggingFace {tuple(tensor.shape)}, "
                    f"Megatron {tuple(parameter.shape)}"
                )
            parameter.copy_(tensor.to(device=parameter.device, dtype=parameter.dtype))

from __future__ import annotations

import re

import torch

from .common import SafetensorReader, merge_gate_up, merge_qkv, strip_mcore_wrappers


def _direct_tensor(name: str, reader: SafetensorReader, config) -> torch.Tensor | None:
    mapping = {
        "embedding.word_embeddings.weight": "model.embed_tokens.weight",
        "decoder.final_layernorm.weight": "model.norm.weight",
        "output_layer.weight": (
            "model.embed_tokens.weight"
            if getattr(config, "tie_word_embeddings", False) or "lm_head.weight" not in reader
            else "lm_head.weight"
        ),
    }
    return reader.get_tensor(mapping[name]) if name in mapping else None


def _layer(name: str) -> tuple[int, str]:
    match = re.fullmatch(r"decoder\.layers\.(\d+)\.(.+)", name)
    if not match:
        raise KeyError(f"Unsupported Megatron parameter {name!r}")
    return int(match.group(1)), match.group(2)


def _attention_tensor(
    rest: str,
    prefix: str,
    reader: SafetensorReader,
    config,
) -> torch.Tensor | None:
    mapping = {
        "self_attention.linear_proj.weight": "self_attn.o_proj.weight",
        "self_attention.linear_proj.bias": "self_attn.o_proj.bias",
        "self_attention.linear_qkv.layer_norm_weight": "input_layernorm.weight",
        "self_attention.q_layernorm.weight": "self_attn.q_norm.weight",
        "self_attention.k_layernorm.weight": "self_attn.k_norm.weight",
        "self_attention.core_attention.softmax_offset": "self_attn.sinks",
    }
    if rest in mapping:
        return reader.get_tensor(f"{prefix}.{mapping[rest]}")
    match = re.fullmatch(r"self_attention\.linear_qkv\.(weight|bias)", rest)
    if match:
        suffix = match.group(1)
        return merge_qkv(
            *(reader.get_tensor(f"{prefix}.self_attn.{projection}_proj.{suffix}") for projection in "qkv"),
            config,
        )
    return None


def qwen_hf_tensor(name: str, reader: SafetensorReader, config) -> torch.Tensor:
    name = strip_mcore_wrappers(name)
    if (tensor := _direct_tensor(name, reader, config)) is not None:
        return tensor

    layer, rest = _layer(name)
    prefix = f"model.layers.{layer}"
    if (tensor := _attention_tensor(rest, prefix, reader, config)) is not None:
        return tensor

    mapping = {
        "mlp.linear_fc1.layer_norm_weight": "post_attention_layernorm.weight",
        "pre_mlp_layernorm.weight": "post_attention_layernorm.weight",
        "mlp.linear_fc2.weight": "mlp.down_proj.weight",
    }
    if rest in mapping:
        return reader.get_tensor(f"{prefix}.{mapping[rest]}")
    if rest == "mlp.linear_fc1.weight":
        return merge_gate_up(
            reader.get_tensor(f"{prefix}.mlp.gate_proj.weight"),
            reader.get_tensor(f"{prefix}.mlp.up_proj.weight"),
        )
    raise KeyError(f"Unsupported Qwen/Llama Megatron parameter {name!r}")


def _qwen_moe_layer_tensor(
    rest: str,
    prefix: str,
    reader: SafetensorReader,
) -> torch.Tensor | None:
    mapping = {
        "pre_mlp_layernorm.weight": "post_attention_layernorm.weight",
        "mlp.linear_fc1.layer_norm_weight": "post_attention_layernorm.weight",
        "mlp.router.weight": "mlp.gate.weight",
        "mlp.router.expert_bias": "mlp.gate.e_score_correction_bias",
        "mlp.shared_experts.linear_fc2.weight": "mlp.shared_expert.down_proj.weight",
        "mlp.shared_experts.gate_weight": "mlp.shared_expert_gate.weight",
    }
    if rest in mapping:
        return reader.get_tensor(f"{prefix}.{mapping[rest]}")
    if rest in {"mlp.shared_experts.linear_fc1.weight", "shared_experts.linear_fc1.weight"}:
        return merge_gate_up(
            reader.get_tensor(f"{prefix}.mlp.shared_expert.gate_proj.weight"),
            reader.get_tensor(f"{prefix}.mlp.shared_expert.up_proj.weight"),
        )
    if rest == "shared_experts.linear_fc2.weight":
        return reader.get_tensor(f"{prefix}.mlp.shared_expert.down_proj.weight")
    if rest == "shared_experts.gate_weight":
        return reader.get_tensor(f"{prefix}.mlp.shared_expert_gate.weight")

    match = re.fullmatch(r"mlp\.experts\.linear_fc([12])\.(weight|bias)(\d+)", rest)
    if match:
        projection, kind, expert = match.groups()
        if projection == "1":
            return merge_gate_up(
                reader.get_tensor(f"{prefix}.mlp.experts.{expert}.gate_proj.{kind}"),
                reader.get_tensor(f"{prefix}.mlp.experts.{expert}.up_proj.{kind}"),
            )
        return reader.get_tensor(f"{prefix}.mlp.experts.{expert}.down_proj.{kind}")
    return None


def qwen_moe_hf_tensor(name: str, reader: SafetensorReader, config) -> torch.Tensor:
    name = strip_mcore_wrappers(name)
    if (tensor := _direct_tensor(name, reader, config)) is not None:
        return tensor

    layer, rest = _layer(name)
    prefix = f"model.layers.{layer}"
    if (tensor := _attention_tensor(rest, prefix, reader, config)) is not None:
        return tensor
    if (tensor := _qwen_moe_layer_tensor(rest, prefix, reader)) is not None:
        return tensor
    return qwen_hf_tensor(name, reader, config)


def mimo_hf_tensor(name: str, reader: SafetensorReader, config) -> torch.Tensor:
    name = strip_mcore_wrappers(name)
    match = re.fullmatch(r"mtp\.layers\.(\d+)\.(.+)", name)
    if not match:
        return qwen_hf_tensor(name, reader, config)

    layer, rest = match.groups()
    mapping = {
        "enorm.weight": "token_layernorm.weight",
        "hnorm.weight": "hidden_layernorm.weight",
        "eh_proj.weight": "input_proj.weight",
        "final_layernorm.weight": "final_layernorm.weight",
    }
    if rest in mapping:
        tensor = reader.get_tensor(f"model.mtp_layers.{layer}.{mapping[rest]}")
        if rest == "eh_proj.weight":
            tensor = torch.cat(tensor.chunk(2, dim=1)[::-1], dim=1)
        return tensor

    proxy = f"decoder.layers.{layer}." + rest.removeprefix("transformer_layer.")
    hf_prefix = f"model.mtp_layers.{layer}"
    _, proxy_rest = _layer(proxy)
    if (tensor := _attention_tensor(proxy_rest, hf_prefix, reader, config)) is not None:
        return tensor
    mapping = {
        "mlp.linear_fc1.layer_norm_weight": "post_attention_layernorm.weight",
        "mlp.linear_fc2.weight": "mlp.down_proj.weight",
    }
    if proxy_rest in mapping:
        return reader.get_tensor(f"{hf_prefix}.{mapping[proxy_rest]}")
    if proxy_rest == "mlp.linear_fc1.weight":
        return merge_gate_up(
            reader.get_tensor(f"{hf_prefix}.mlp.gate_proj.weight"),
            reader.get_tensor(f"{hf_prefix}.mlp.up_proj.weight"),
        )
    raise KeyError(f"Unsupported MiMo Megatron parameter {name!r}")


def minimax_m2_hf_tensor(name: str, reader: SafetensorReader, config) -> torch.Tensor:
    name = strip_mcore_wrappers(name)
    if (tensor := _direct_tensor(name, reader, config)) is not None:
        return tensor
    layer, rest = _layer(name)
    prefix = f"model.layers.{layer}"
    if (tensor := _attention_tensor(rest, prefix, reader, config)) is not None:
        return tensor
    mapping = {
        "pre_mlp_layernorm.weight": "post_attention_layernorm.weight",
        "mlp.router.weight": "block_sparse_moe.gate.weight",
        "mlp.router.expert_bias": "block_sparse_moe.e_score_correction_bias",
        "self_attention.q_norm.weight": "self_attn.q_norm.weight",
        "self_attention.k_norm.weight": "self_attn.k_norm.weight",
    }
    if rest in mapping:
        return reader.get_tensor(f"{prefix}.{mapping[rest]}")
    match = re.fullmatch(r"mlp\.experts\.linear_fc([12])\.weight(\d+)", rest)
    if match:
        projection, expert = match.groups()
        if projection == "1":
            return merge_gate_up(
                reader.get_tensor(f"{prefix}.block_sparse_moe.experts.{expert}.w1.weight"),
                reader.get_tensor(f"{prefix}.block_sparse_moe.experts.{expert}.w3.weight"),
            )
        return reader.get_tensor(f"{prefix}.block_sparse_moe.experts.{expert}.w2.weight")
    raise KeyError(f"Unsupported MiniMax-M2 Megatron parameter {name!r}")

import ast
import logging

from megatron.training.arguments import parse_args as _megatron_parse_args
from megatron.training.arguments import validate_args as _megatron_validate_args
from transformers import AutoConfig

try:
    from megatron.core.tokenizers.utils.build_tokenizer import vocab_size_with_padding as _vocab_size_with_padding
except ImportError:
    from megatron.training.tokenizer.tokenizer import _vocab_size_with_padding

__all__ = ["validate_args", "megatron_parse_args", "set_default_megatron_args"]

logger = logging.getLogger(__name__)


_ALLGATHER_CP_DSA_ARCHITECTURES = {
    "DeepseekV32ForCausalLM",
    "GlmMoeDsaForCausalLM",
}


def _is_allgather_cp_dsa_model(hf_config):
    if hf_config is None:
        return False

    architecture_names = getattr(hf_config, "architectures", None) or []
    return any(name in _ALLGATHER_CP_DSA_ARCHITECTURES for name in architecture_names)


def _validate_allgather_cp_supported(args, hf_config=None):
    if not getattr(args, "allgather_cp", False) or getattr(args, "context_parallel_size", 1) <= 1:
        return

    if _is_allgather_cp_dsa_model(hf_config):
        return

    raise ValueError(
        "--allgather-cp with --context-parallel-size > 1 is currently only supported for "
        "DSA attention models (DeepSeek-V3.2 and GLM-5.1). Non-DSA models still use the "
        "zigzag CP layout and would silently scramble token order under allgather CP. "
        "Please remove --allgather-cp, set --context-parallel-size 1, or use a supported DSA model."
    )


def _has_dense_moe_layers(args):
    moe_layer_freq = getattr(args, "moe_layer_freq", None)
    if moe_layer_freq is None:
        return True

    if isinstance(moe_layer_freq, str):
        try:
            moe_layer_freq = ast.literal_eval(moe_layer_freq)
        except (SyntaxError, ValueError):
            return "0" in moe_layer_freq

    try:
        return any(int(layer_freq) == 0 for layer_freq in moe_layer_freq)
    except TypeError:
        return int(moe_layer_freq) == 0


def _is_moe_config(hf_config):
    return any(
        hasattr(hf_config, attr)
        for attr in (
            "moe_intermediate_size",
            "num_experts",
            "n_routed_experts",
            "num_local_experts",
        )
    )


def validate_args(args):
    """Run megatron's own validate_args plus slime-specific megatron validations."""

    _megatron_validate_args(args)

    # always use varlen
    args.variable_seq_lengths = True
    if getattr(args, "moe_token_dispatcher_type", None) == "allgather":
        logger.info(
            "--moe-token-dispatcher-type allgather does not support variable sequence length, "
            "please use alltoall dispatcher instead."
        )
        args.moe_token_dispatcher_type = "alltoall"

    if args.pipeline_model_parallel_size == 1:
        assert args.decoder_first_pipeline_num_layers is None and args.decoder_last_pipeline_num_layers is None, (
            "decoder_first_pipeline_num_layers and decoder_last_pipeline_num_layers should be None when "
            "pipeline_model_parallel_size is 1."
        )


def _hf_validate_args(args, hf_config):
    def equal(x, y):
        return x == y

    errors = []

    # multimodal models have different config structure
    if hasattr(hf_config, "text_config"):
        hf_config = hf_config.text_config

    # Some models store rope_theta inside rope_parameters dict rather than
    # as a top-level attribute.  Prefer the dict value when available so
    # the validation doesn't compare against a stale class default.
    rope_params = getattr(hf_config, "rope_parameters", None)
    if isinstance(rope_params, dict) and "rope_theta" in rope_params:
        _hf_rope_theta = rope_params["rope_theta"]
    else:
        _hf_rope_theta = getattr(hf_config, "rope_theta", None)

    validate_dense_ffn = not _is_moe_config(hf_config) or _has_dense_moe_layers(args)

    for hf_config_name, megatron_config_name, compare_fn in [
        ("hidden_size", "hidden_size", equal),
        ("num_attention_heads", "num_attention_heads", equal),
        ("num_hidden_layers", "num_layers", equal),
        ("intermediate_size", "ffn_hidden_size", equal),
        ("moe_intermediate_size", "moe_ffn_hidden_size", equal),
        ("shared_expert_intermediate_size", "moe_shared_expert_intermediate_size", equal),
        ("tie_word_embeddings", "untie_embeddings_and_output_weights", lambda x, y: not x == y),
        ("rms_norm_eps", "norm_epsilon", equal),
        ("rms_norm_eps", "layernorm_epsilon", equal),
    ]:
        if hf_config_name == "intermediate_size" and not validate_dense_ffn:
            continue

        if hasattr(hf_config, hf_config_name) and hasattr(args, megatron_config_name):
            if not compare_fn(getattr(hf_config, hf_config_name), getattr(args, megatron_config_name)):
                errors.append(
                    f"{hf_config_name} in hf config {getattr(hf_config, hf_config_name)} is not equal to "
                    f"{megatron_config_name} {getattr(args, megatron_config_name)}, please check the config."
                )

    # Validate rope_theta separately using the resolved value
    if _hf_rope_theta is not None:
        if not equal(_hf_rope_theta, getattr(args, "rotary_base", None)):
            errors.append(
                f"rope_theta in hf config {_hf_rope_theta} is not equal to "
                f"rotary_base {getattr(args, 'rotary_base', None)}, please check the config."
            )

    if len(errors) > 0:
        raise AssertionError("hf_validate_args failed: " + "; ".join(errors))


def _set_default_megatron_args(args):
    # always use zero optimizer
    args.use_distributed_optimizer = True
    if not hasattr(args, "enable_gloo_process_groups"):
        args.enable_gloo_process_groups = True
    # TODO: maybe change this after megatron has good fp8 support
    args.bf16 = not args.fp16
    # Checkpoint I/O defaults: these keep checkpoint contents unchanged while
    # reducing repeated validation/planning work and parallelizing load.
    args.use_persistent_ckpt_worker = True
    args.ckpt_assume_constant_structure = True
    args.ckpt_fully_parallel_load = True
    # placeholders
    if args.seq_length is None:
        args.seq_length = 4096
    # Megatron also uses this value as YaRN's original context length. Preserve
    # the checkpoint/model value when the launcher supplied one explicitly.
    if args.max_position_embeddings is None:
        args.max_position_embeddings = args.seq_length
    # TODO: revisit this when megatron(dev) have solved the optimizer-cpu-offload ckpt saving bug
    args.dist_ckpt_save_pre_mcore_014 = True
    # compatible for megatron
    if hasattr(args, "rope_type") and args.rope_type is None:
        args.rope_type = "yarn" if args.multi_latent_attention else "rope"

    if args.vocab_size and not args.padded_vocab_size:
        args.padded_vocab_size = _vocab_size_with_padding(args.vocab_size, args)

    if not args.tokenizer_model and not args.tokenizer_type:
        logger.info("--tokenizer-model not set, use --hf-checkpoint as tokenizer model.")
        args.tokenizer_model = args.hf_checkpoint
        args.tokenizer_type = "HuggingFaceTokenizer"
    elif not args.tokenizer_model:
        logger.info("--tokenizer-model not set, use --hf-checkpoint as tokenizer model.")
        args.tokenizer_model = args.hf_checkpoint
    return args


# Public alias for external tools (e.g. convert_hf_to_torch_dist.py)
set_default_megatron_args = _set_default_megatron_args


def megatron_parse_args(extra_args_provider, skip_hf_validate=False):
    """Parse megatron args, validate HF config, and set defaults."""
    args = _megatron_parse_args(extra_args_provider=extra_args_provider, ignore_unknown_args=True)

    hf_config = None
    if args.hf_checkpoint and not skip_hf_validate:
        hf_config = AutoConfig.from_pretrained(args.hf_checkpoint, trust_remote_code=True)
        _hf_validate_args(args, hf_config)

    if not skip_hf_validate:
        _validate_allgather_cp_supported(args, hf_config)

    args.rank = 0
    args.world_size = args.actor_num_nodes * args.actor_num_gpus_per_node
    args = _set_default_megatron_args(args)
    return args

import abc
import logging
import os
import random
from datetime import timedelta

import ray
import torch
import torch.distributed as dist

import slime.utils.eval_config
from slime.observability.logging_utils import configure_logger
from slime.ray.ray_actor import RayActor
from slime.utils import accelerator
from slime.utils.distributed_utils import init_gloo_group
from slime.utils.memory_utils import clear_memory, print_memory

logger = logging.getLogger(__name__)


def get_local_gpu_id():
    return accelerator.resolve_visible_device_id(ray.get_gpu_ids()[0])


class TrainRayActor(RayActor):
    def __init__(self, world_size, rank, master_addr, master_port):
        configure_logger()

        self._world_size = world_size
        self._rank = rank
        if master_addr:
            self.master_addr, self.master_port = master_addr, master_port
        else:
            self.master_addr, self.master_port = self._get_current_node_ip_and_free_port(
                start_port=random.randint(20000, 21000)
            )

        os.environ["MASTER_ADDR"] = self.master_addr
        os.environ["MASTER_PORT"] = str(self.master_port)
        os.environ["WORLD_SIZE"] = str(self._world_size)
        os.environ["RANK"] = str(self._rank)
        # TODO: currently this doesn't work as ray has already set torch.cuda.device_count().
        # os.environ.pop("CUDA_VISIBLE_DEVICES", None)
        # os.environ["LOCAL_RANK"] = str(ray.get_gpu_ids()[0])
        os.environ["LOCAL_RANK"] = str(get_local_gpu_id())

    def init(self, args, role, with_ref=False, with_opd_teacher=False):
        self.args = args
        self.role = role
        self.with_ref = with_ref
        self.with_opd_teacher = with_opd_teacher

        torch.serialization.add_safe_globals([slime.utils.eval_config.EvalDatasetConfig])

        local_rank = int(os.environ.get("LOCAL_RANK", 0))
        accelerator.set_device(local_rank)
        if accelerator.set_allocator_expandable_segments():
            logger.info(
                f"[Rank {self._rank}] Enabled {accelerator.device_type().upper()} memory allocator "
                "expandable_segments for train actor"
            )

        backend = accelerator.process_group_backend(args.distributed_backend)

        dist.init_process_group(
            backend=backend,
            timeout=timedelta(minutes=args.distributed_timeout_minutes),
        )
        init_gloo_group()

        args.rank = dist.get_rank()
        args.world_size = dist.get_world_size()

        try:
            if torch.version.hip is not None:
                logger.info("Detected ROCm/HIP environment, skipping NUMA affinity setup")
                # will find the coresponding API to implement ROCm version as below
            else:
                import pynvml

                pynvml.nvmlInit()

                local_rank = int(os.environ["RANK"]) % args.num_gpus_per_node

                handle = pynvml.nvmlDeviceGetHandleByIndex(local_rank)
                pynvml.nvmlDeviceSetCpuAffinity(handle)

                logger.info(f"Set NUMA affinity for GPU {local_rank}")
                pynvml.nvmlShutdown()

        except ImportError:
            logger.info("Warning: pynvml not available, skipping NUMA affinity setup")
        except Exception as e:
            logger.info(f"Warning: Failed to set NUMA affinity: {e}")

    def clear_memory(self):
        if self.args.debug_rollout_only:
            return
        print_memory("before TrainRayActor.clear_memory")
        clear_memory()
        print_memory("after TrainRayActor.clear_memory")

    @abc.abstractmethod
    def sleep(self, tags):
        raise NotImplementedError

    @abc.abstractmethod
    def wake_up(self, tags):
        raise NotImplementedError

    @abc.abstractmethod
    def train(self, rollout_id, rollout_data_ref, external_data=None):
        raise NotImplementedError

    @abc.abstractmethod
    def save_model(self, rollout_id, force_sync=False):
        raise NotImplementedError

    @abc.abstractmethod
    def update_weights(self):
        raise NotImplementedError

    def set_rollout_manager(self, rollout_manager):
        self.rollout_manager = rollout_manager
        if not self.args.debug_rollout_only and self.args.rank == 0:
            ray.get(self.rollout_manager.set_train_parallel_config.remote(self.train_parallel_config))

from __future__ import annotations

import functools
import json
from collections.abc import Callable
from pathlib import Path

import torch
import torch.nn.functional as F
from safetensors import safe_open


class SafetensorReader:
    def __init__(self, path: str | Path):
        self.path = Path(path)
        index_path = self.path / "model.safetensors.index.json"
        if index_path.is_file():
            with index_path.open() as index_file:
                self.weight_map = json.load(index_file)["weight_map"]
        else:
            files = sorted(self.path.glob("*.safetensors"))
            if not files:
                raise FileNotFoundError(f"No safetensors checkpoint found in {self.path}")
            self.weight_map = {}
            for file in files:
                with safe_open(file, framework="pt", device="cpu") as tensors:
                    self.weight_map.update(dict.fromkeys(tensors.keys(), file.name))
        self._files = {}

    def __contains__(self, name: str) -> bool:
        return name in self.weight_map

    @functools.lru_cache(maxsize=1)  # noqa: B019 - cache belongs to this reader instance
    def get_tensor(self, name: str) -> torch.Tensor:
        try:
            filename = self.weight_map[name]
        except KeyError as exc:
            raise KeyError(f"HuggingFace checkpoint does not contain {name!r}") from exc
        if filename not in self._files:
            self._files[filename] = safe_open(self.path / filename, framework="pt", device="cpu")
        tensor = self._files[filename].get_tensor(name)
        scale_name = f"{name}_scale_inv"
        if tensor.element_size() == 1 and scale_name in self:
            scale_file = self.weight_map[scale_name]
            if scale_file not in self._files:
                self._files[scale_file] = safe_open(self.path / scale_file, framework="pt", device="cpu")
            scale = self._files[scale_file].get_tensor(scale_name).to(torch.bfloat16)
            rows, columns = tensor.shape
            block_rows, block_columns = scale.shape
            tensor = F.pad(
                tensor.to(torch.bfloat16),
                (0, block_columns * 128 - columns, 0, block_rows * 128 - rows),
            )
            tensor = tensor.view(block_rows, 128, block_columns, 128)
            tensor.mul_(scale[:, None, :, None])
            tensor = tensor.reshape(block_rows * 128, block_columns * 128)[:rows, :columns]
        return tensor


def strip_mcore_wrappers(name: str) -> str:
    while name.startswith("module."):
        name = name.removeprefix("module.")
    return name.removeprefix("language_model.")


def text_config(config):
    return getattr(config, "text_config", config)


def merge_qkv(q: torch.Tensor, k: torch.Tensor, v: torch.Tensor, config) -> torch.Tensor:
    config = text_config(config)
    num_groups = config.num_key_value_heads
    num_heads = config.num_attention_heads
    head_dim = getattr(config, "head_dim", None) or config.hidden_size // num_heads
    trailing_shape = q.shape[1:]
    q = q.reshape(num_groups, num_heads // num_groups * head_dim, *trailing_shape)
    k = k.reshape(num_groups, head_dim, *trailing_shape)
    v = v.reshape(num_groups, head_dim, *trailing_shape)
    return torch.cat((q, k, v), dim=1).reshape(-1, *trailing_shape).contiguous()


def merge_gate_up(gate: torch.Tensor, up: torch.Tensor) -> torch.Tensor:
    return torch.cat((gate, up), dim=0)


def _tensor_parallel_shard(
    name: str,
    tensor: torch.Tensor,
    *,
    parallel_size: int,
    parallel_rank: int,
    partition_dim: int,
    partition_stride: int,
) -> torch.Tensor:
    if parallel_size == 1:
        return tensor

    if "linear_fc1.weight" in name or "linear_fc1.bias" in name:
        gate, up = tensor.chunk(2, dim=partition_dim)
        gate = torch.chunk(gate, parallel_size, dim=partition_dim)[parallel_rank]
        up = torch.chunk(up, parallel_size, dim=partition_dim)[parallel_rank]
        return torch.cat((gate, up), dim=partition_dim).contiguous()

    if "linear_fc2.weight" in name and partition_dim == 0:
        partition_dim = 1

    chunks = torch.chunk(tensor, parallel_size * partition_stride, dim=partition_dim)
    return torch.cat(chunks[parallel_rank::parallel_size], dim=partition_dim).contiguous()


def shard_mcore_tensor(name: str, tensor: torch.Tensor, parameter: torch.Tensor) -> torch.Tensor:
    from megatron.core import mpu

    if (
        not getattr(parameter, "tensor_model_parallel", False)
        or getattr(parameter, "parallel_mode", None) == "duplicated"
    ):
        return tensor

    if ".experts." in name:
        parallel_size = mpu.get_expert_tensor_parallel_world_size()
        parallel_rank = mpu.get_expert_tensor_parallel_rank()
    else:
        parallel_size = mpu.get_tensor_model_parallel_world_size()
        parallel_rank = mpu.get_tensor_model_parallel_rank()

    return _tensor_parallel_shard(
        name,
        tensor,
        parallel_size=parallel_size,
        parallel_rank=parallel_rank,
        partition_dim=parameter.partition_dim,
        partition_stride=parameter.partition_stride,
    )


def _pad_vocab(args, name: str, tensor: torch.Tensor) -> torch.Tensor:
    if not (name.endswith("embedding.word_embeddings.weight") or name.endswith("output_layer.weight")):
        return tensor
    padded_size = getattr(args, "padded_vocab_size", None)
    if padded_size is None or tensor.shape[0] >= padded_size:
        return tensor
    return F.pad(tensor, (0, 0, 0, padded_size - tensor.shape[0]))


def load_model_hf_weights(
    args,
    model,
    path: str | Path,
    config,
    get_hf_tensor: Callable[[str, SafetensorReader, object], torch.Tensor],
) -> None:
    from slime.backends.megatron_utils.update_weight.common import named_params_and_buffers

    reader = SafetensorReader(path)
    with torch.no_grad():
        for name, parameter in named_params_and_buffers(args, model):
            tensor = get_hf_tensor(name, reader, config)
            if name.endswith("output_layer.weight") and parameter.shape[0] == 1 and tensor.shape[0] != 1:
                continue
            tensor = shard_mcore_tensor(name, _pad_vocab(args, name, tensor), parameter)
            if tensor.shape != parameter.shape:
                raise ValueError(
                    f"Shape mismatch loading {name}: HuggingFace {tuple(tensor.shape)}, "
                    f"Megatron {tuple(parameter.shape)}"
                )
            parameter.copy_(tensor.to(device=parameter.device, dtype=parameter.dtype))

from __future__ import annotations

import re

import torch

from .common import SafetensorReader, merge_gate_up, merge_qkv, strip_mcore_wrappers


def _direct_tensor(name: str, reader: SafetensorReader, config) -> torch.Tensor | None:
    mapping = {
        "embedding.word_embeddings.weight": "model.embed_tokens.weight",
        "decoder.final_layernorm.weight": "model.norm.weight",
        "output_layer.weight": (
            "model.embed_tokens.weight"
            if getattr(config, "tie_word_embeddings", False) or "lm_head.weight" not in reader
            else "lm_head.weight"
        ),
    }
    return reader.get_tensor(mapping[name]) if name in mapping else None


def _layer(name: str) -> tuple[int, str]:
    match = re.fullmatch(r"decoder\.layers\.(\d+)\.(.+)", name)
    if not match:
        raise KeyError(f"Unsupported Megatron parameter {name!r}")
    return int(match.group(1)), match.group(2)


def _attention_tensor(
    rest: str,
    prefix: str,
    reader: SafetensorReader,
    config,
) -> torch.Tensor | None:
    mapping = {
        "self_attention.linear_proj.weight": "self_attn.o_proj.weight",
        "self_attention.linear_proj.bias": "self_attn.o_proj.bias",
        "self_attention.linear_qkv.layer_norm_weight": "input_layernorm.weight",
        "self_attention.q_layernorm.weight": "self_attn.q_norm.weight",
        "self_attention.k_layernorm.weight": "self_attn.k_norm.weight",
        "self_attention.core_attention.softmax_offset": "self_attn.sinks",
    }
    if rest in mapping:
        return reader.get_tensor(f"{prefix}.{mapping[rest]}")
    match = re.fullmatch(r"self_attention\.linear_qkv\.(weight|bias)", rest)
    if match:
        suffix = match.group(1)
        return merge_qkv(
            *(reader.get_tensor(f"{prefix}.self_attn.{projection}_proj.{suffix}") for projection in "qkv"),
            config,
        )
    return None


def qwen_hf_tensor(name: str, reader: SafetensorReader, config) -> torch.Tensor:
    name = strip_mcore_wrappers(name)
    if (tensor := _direct_tensor(name, reader, config)) is not None:
        return tensor

    layer, rest = _layer(name)
    prefix = f"model.layers.{layer}"
    if (tensor := _attention_tensor(rest, prefix, reader, config)) is not None:
        return tensor

    mapping = {
        "mlp.linear_fc1.layer_norm_weight": "post_attention_layernorm.weight",
        "pre_mlp_layernorm.weight": "post_attention_layernorm.weight",
        "mlp.linear_fc2.weight": "mlp.down_proj.weight",
    }
    if rest in mapping:
        return reader.get_tensor(f"{prefix}.{mapping[rest]}")
    if rest == "mlp.linear_fc1.weight":
        return merge_gate_up(
            reader.get_tensor(f"{prefix}.mlp.gate_proj.weight"),
            reader.get_tensor(f"{prefix}.mlp.up_proj.weight"),
        )
    raise KeyError(f"Unsupported Qwen/Llama Megatron parameter {name!r}")


def _qwen_moe_layer_tensor(
    rest: str,
    prefix: str,
    reader: SafetensorReader,
) -> torch.Tensor | None:
    mapping = {
        "pre_mlp_layernorm.weight": "post_attention_layernorm.weight",
        "mlp.linear_fc1.layer_norm_weight": "post_attention_layernorm.weight",
        "mlp.router.weight": "mlp.gate.weight",
        "mlp.router.expert_bias": "mlp.gate.e_score_correction_bias",
        "mlp.shared_experts.linear_fc2.weight": "mlp.shared_expert.down_proj.weight",
        "mlp.shared_experts.gate_weight": "mlp.shared_expert_gate.weight",
    }
    if rest in mapping:
        return reader.get_tensor(f"{prefix}.{mapping[rest]}")
    if rest in {"mlp.shared_experts.linear_fc1.weight", "shared_experts.linear_fc1.weight"}:
        return merge_gate_up(
            reader.get_tensor(f"{prefix}.mlp.shared_expert.gate_proj.weight"),
            reader.get_tensor(f"{prefix}.mlp.shared_expert.up_proj.weight"),
        )
    if rest == "shared_experts.linear_fc2.weight":
        return reader.get_tensor(f"{prefix}.mlp.shared_expert.down_proj.weight")
    if rest == "shared_experts.gate_weight":
        return reader.get_tensor(f"{prefix}.mlp.shared_expert_gate.weight")

    match = re.fullmatch(r"mlp\.experts\.linear_fc([12])\.(weight|bias)(\d+)", rest)
    if match:
        projection, kind, expert = match.groups()
        if projection == "1":
            return merge_gate_up(
                reader.get_tensor(f"{prefix}.mlp.experts.{expert}.gate_proj.{kind}"),
                reader.get_tensor(f"{prefix}.mlp.experts.{expert}.up_proj.{kind}"),
            )
        return reader.get_tensor(f"{prefix}.mlp.experts.{expert}.down_proj.{kind}")
    return None


def qwen_moe_hf_tensor(name: str, reader: SafetensorReader, config) -> torch.Tensor:
    name = strip_mcore_wrappers(name)
    if (tensor := _direct_tensor(name, reader, config)) is not None:
        return tensor

    layer, rest = _layer(name)
    prefix = f"model.layers.{layer}"
    if (tensor := _attention_tensor(rest, prefix, reader, config)) is not None:
        return tensor
    if (tensor := _qwen_moe_layer_tensor(rest, prefix, reader)) is not None:
        return tensor
    return qwen_hf_tensor(name, reader, config)


def mimo_hf_tensor(name: str, reader: SafetensorReader, config) -> torch.Tensor:
    name = strip_mcore_wrappers(name)
    match = re.fullmatch(r"mtp\.layers\.(\d+)\.(.+)", name)
    if not match:
        return qwen_hf_tensor(name, reader, config)

    layer, rest = match.groups()
    mapping = {
        "enorm.weight": "token_layernorm.weight",
        "hnorm.weight": "hidden_layernorm.weight",
        "eh_proj.weight": "input_proj.weight",
        "final_layernorm.weight": "final_layernorm.weight",
    }
    if rest in mapping:
        tensor = reader.get_tensor(f"model.mtp_layers.{layer}.{mapping[rest]}")
        if rest == "eh_proj.weight":
            tensor = torch.cat(tensor.chunk(2, dim=1)[::-1], dim=1)
        return tensor

    proxy = f"decoder.layers.{layer}." + rest.removeprefix("transformer_layer.")
    hf_prefix = f"model.mtp_layers.{layer}"
    _, proxy_rest = _layer(proxy)
    if (tensor := _attention_tensor(proxy_rest, hf_prefix, reader, config)) is not None:
        return tensor
    mapping = {
        "mlp.linear_fc1.layer_norm_weight": "post_attention_layernorm.weight",
        "mlp.linear_fc2.weight": "mlp.down_proj.weight",
    }
    if proxy_rest in mapping:
        return reader.get_tensor(f"{hf_prefix}.{mapping[proxy_rest]}")
    if proxy_rest == "mlp.linear_fc1.weight":
        return merge_gate_up(
            reader.get_tensor(f"{hf_prefix}.mlp.gate_proj.weight"),
            reader.get_tensor(f"{hf_prefix}.mlp.up_proj.weight"),
        )
    raise KeyError(f"Unsupported MiMo Megatron parameter {name!r}")


def minimax_m2_hf_tensor(name: str, reader: SafetensorReader, config) -> torch.Tensor:
    name = strip_mcore_wrappers(name)
    if (tensor := _direct_tensor(name, reader, config)) is not None:
        return tensor
    layer, rest = _layer(name)
    prefix = f"model.layers.{layer}"
    if (tensor := _attention_tensor(rest, prefix, reader, config)) is not None:
        return tensor
    mapping = {
        "pre_mlp_layernorm.weight": "post_attention_layernorm.weight",
        "mlp.router.weight": "block_sparse_moe.gate.weight",
        "mlp.router.expert_bias": "block_sparse_moe.e_score_correction_bias",
        "self_attention.q_norm.weight": "self_attn.q_norm.weight",
        "self_attention.k_norm.weight": "self_attn.k_norm.weight",
    }
    if rest in mapping:
        return reader.get_tensor(f"{prefix}.{mapping[rest]}")
    match = re.fullmatch(r"mlp\.experts\.linear_fc([12])\.weight(\d+)", rest)
    if match:
        projection, expert = match.groups()
        if projection == "1":
            return merge_gate_up(
                reader.get_tensor(f"{prefix}.block_sparse_moe.experts.{expert}.w1.weight"),
                reader.get_tensor(f"{prefix}.block_sparse_moe.experts.{expert}.w3.weight"),
            )
        return reader.get_tensor(f"{prefix}.block_sparse_moe.experts.{expert}.w2.weight")
    raise KeyError(f"Unsupported MiniMax-M2 Megatron parameter {name!r}")

# Adapt from https://github.com/NVIDIA/Megatron-LM/blob/b1efb3c7126ef7615e8c333432d76e08038e17ff/pretrain_gpt.py
import argparse
import inspect
import re
from contextlib import nullcontext
from typing import Literal

import torch
from megatron.core import tensor_parallel
from megatron.core.models.gpt import GPTModel
from megatron.core.models.gpt.gpt_layer_specs import (
    get_gpt_decoder_block_spec,
    get_gpt_layer_local_spec,
    get_gpt_layer_with_transformer_engine_spec,
)
from megatron.core.transformer.spec_utils import import_module
from megatron.core.transformer.transformer_config import TransformerConfig
from megatron.training.arguments import core_transformer_config_from_args

from slime.utils.misc import load_function

_INDEXER_DIRECT_SUBMODULE_NAMES = frozenset(
    {
        "wq_b",
        "wk",
        "k_norm",
        "weights_proj",
        "index_kpool_compress_ape",
        "index_kpool_compress_gate",
    }
)


def _is_indexer_parameter(name: str) -> bool:
    """Return whether *name* belongs to a DSA indexer.

    The GLM plugin exposes indexer projections directly under
    ``self_attention``. Megatron's upstream DSA implementation instead nests
    them under ``self_attention.core_attention.indexer``. Keep the ownership
    check structural so similarly named non-indexer projections stay trainable.
    """

    parts = name.split(".")
    for index, part in enumerate(parts):
        if part != "self_attention" or index + 1 >= len(parts):
            continue
        attention_parts = parts[index + 1 :]
        if attention_parts[0] in _INDEXER_DIRECT_SUBMODULE_NAMES:
            return True
        if "indexer" in attention_parts[:-1]:
            return True
    return False


# Adapt from https://github.com/volcengine/verl/blob/c3b20575d2bc815fcccd84bddb4c0401fc4b632b/verl/models/llama/megatron/layers/parallel_linear.py#L82
class LinearForLastLayer(torch.nn.Linear):
    # WORKSPACE CHANGE, part of the shared setup: `bias` defaults to False
    # here, where upstream slime v0.3.2 defaults it to True.
    #
    # Upstream cannot load a critic from a HuggingFace checkpoint at all. The
    # HF loader walks every Megatron parameter and asks the model's mapper for
    # a source tensor; `output_layer.weight` is special-cased (a [1, hidden]
    # value head is skipped when the HF tensor is [vocab, hidden]), but
    # `output_layer.bias` has no HF counterpart and no special case, so
    # `qwen_hf_tensor` raises KeyError("Unsupported Megatron parameter
    # 'output_layer.bias'") before training starts. See
    # slime/backends/megatron_utils/hf_to_megatron/{qwen,common}.py.
    #
    # A value head does not need a bias -- it is one scalar of freedom that
    # V(s) can equally express through the backbone -- and dropping it is the
    # smallest change that lets a critic start from HF weights, which is what
    # Stage B does.
    def __init__(
        self,
        input_size: int,
        output_size: int,
        *,
        config: TransformerConfig,
        bias: bool = False,
    ) -> None:
        super().__init__(in_features=input_size, out_features=output_size, bias=bias)
        self.sequence_parallel = config.sequence_parallel
        if self.sequence_parallel:
            self.weight.sequence_parallel = True
            if bias:
                self.bias.sequence_parallel = True

        init_method_std = getattr(config, "init_method_std", None)
        if init_method_std is None:
            init_method_std = 0.02
        self.weight.data.normal_(mean=0.0, std=init_method_std)
        if bias:
            self.bias.data.zero_()

    def forward(
        self,
        input_: torch.Tensor,
        weight: torch.Tensor | None = None,
        runtime_gather_output: bool | None = None,
    ) -> tuple[torch.Tensor, None]:
        logits = super().forward(input_)
        logits = logits.float()
        if self.sequence_parallel:
            logits = tensor_parallel.gather_from_sequence_parallel_region(logits, tensor_parallel_output_grad=False)
        return logits, None


def _get_model_provider_func(
    args: argparse.Namespace,
    role: Literal["actor", "critic"] = "actor",
):
    # Support custom model provider path (similar to --custom-rm-path for reward models)
    if getattr(args, "custom_model_provider_path", None):

        def wrapped_model_provider(
            pre_process: bool = True, post_process: bool = True, vp_stage: int | None = None
        ) -> GPTModel:
            custom_model_provider = load_function(args.custom_model_provider_path)
            # Check if the custom provider supports vp_stage parameter
            has_vp_stage = "vp_stage" in inspect.signature(custom_model_provider).parameters
            if has_vp_stage:
                model = custom_model_provider(pre_process=pre_process, post_process=post_process, vp_stage=vp_stage)
            else:
                model = custom_model_provider(pre_process=pre_process, post_process=post_process)
            # Apply critic output layer if needed
            if post_process and role == "critic":
                model.output_layer = LinearForLastLayer(
                    input_size=model.config.hidden_size, output_size=1, config=model.config
                )
            return model

        return wrapped_model_provider

    def model_provider(pre_process: bool = True, post_process: bool = True, vp_stage: int | None = None) -> GPTModel:
        """Builds the model.

        If you set the use_legacy_models to True, it will return the legacy GPT model and if not the mcore GPT model.

        Args:
            pre_process (bool, optional): Set to true if you need to compute embedings. Defaults to True.
            post_process (bool, optional): Set to true if you need to want to compute output logits/loss. Defaults to True.


        Returns:
            Union[GPTModel, megatron.legacy.model.GPTModel]: The returned model
        """
        use_te = args.transformer_impl == "transformer_engine"

        # Experimental loading arguments from yaml
        config: TransformerConfig = core_transformer_config_from_args(args)
        # Older GLM Megatron forks consumed this flag from TransformerConfig.
        # Preserve that contract for custom specs, while freeze_model_params()
        # below provides the concrete implementation on current Megatron.
        config.freeze_indexer = getattr(args, "freeze_indexer", False)

        if args.spec is not None:
            transformer_layer_spec = import_module(args.spec)
            # Allow the spec to be a function so that user can use customized Megatron easier.
            if callable(transformer_layer_spec):
                result = transformer_layer_spec(args, config, vp_stage)
                # If the result is itself a model provider (callable with pre_process param),
                # delegate model construction to it directly (e.g. glm-omni VL model).
                if callable(result) and "pre_process" in inspect.signature(result).parameters:
                    model = result(pre_process=pre_process, post_process=post_process, vp_stage=vp_stage)
                    if post_process and role == "critic":
                        model.output_layer = LinearForLastLayer(
                            input_size=config.hidden_size, output_size=1, config=config
                        )
                    return model
                transformer_layer_spec = result
        else:
            if args.num_experts:
                # Define the decoder block spec
                kwargs = {
                    "use_transformer_engine": use_te,
                }
                if vp_stage is not None:
                    kwargs["vp_stage"] = vp_stage
                transformer_layer_spec = get_gpt_decoder_block_spec(config, **kwargs)
            else:
                # Define the decoder layer spec
                if use_te:
                    transformer_layer_spec = get_gpt_layer_with_transformer_engine_spec(
                        num_experts=args.num_experts,
                        moe_grouped_gemm=args.moe_grouped_gemm,
                        qk_layernorm=args.qk_layernorm,
                        multi_latent_attention=args.multi_latent_attention,
                        moe_use_legacy_grouped_gemm=args.moe_use_legacy_grouped_gemm,
                    )
                else:
                    transformer_layer_spec = get_gpt_layer_local_spec(
                        num_experts=args.num_experts,
                        moe_grouped_gemm=args.moe_grouped_gemm,
                        qk_layernorm=args.qk_layernorm,
                        multi_latent_attention=args.multi_latent_attention,
                        moe_use_legacy_grouped_gemm=args.moe_use_legacy_grouped_gemm,
                    )

        build_model_context = nullcontext
        build_model_context_args = {}
        if args.fp8_param_gather:
            try:
                from transformer_engine.pytorch import fp8_model_init

                build_model_context = fp8_model_init
                build_model_context_args["enabled"] = True

                # Check if fp8_model_init supports preserve_high_precision_init_val
                if "preserve_high_precision_init_val" in inspect.signature(fp8_model_init).parameters:
                    build_model_context_args["preserve_high_precision_init_val"] = True
            except Exception as e:
                raise RuntimeError(
                    "--fp8-param-gather requires `fp8_model_init` from TransformerEngine, but not found."
                ) from e

        kwargs = {
            "config": config,
            "transformer_layer_spec": transformer_layer_spec,
            "vocab_size": args.padded_vocab_size,
            "max_sequence_length": args.max_position_embeddings,
            "pre_process": pre_process,
            "post_process": post_process,
            "fp16_lm_cross_entropy": args.fp16_lm_cross_entropy,
            "parallel_output": True,
            "share_embeddings_and_output_weights": not args.untie_embeddings_and_output_weights,
            "position_embedding_type": args.position_embedding_type,
            "rotary_percent": args.rotary_percent,
            "rotary_base": args.rotary_base,
            "rope_scaling": args.use_rope_scaling,
        }

        if vp_stage is not None:
            kwargs["vp_stage"] = vp_stage

        if args.mtp_num_layers:
            from megatron.core.models.gpt.gpt_layer_specs import get_gpt_mtp_block_spec

            mtp_kwargs = {
                "use_transformer_engine": use_te,
            }
            if vp_stage is not None:
                mtp_kwargs["vp_stage"] = vp_stage

            mtp_block_spec = get_gpt_mtp_block_spec(config, transformer_layer_spec, **mtp_kwargs)
            kwargs["mtp_block_spec"] = mtp_block_spec

        with build_model_context(**build_model_context_args):
            model = GPTModel(**kwargs)

        if post_process and role == "critic":
            model.output_layer = LinearForLastLayer(input_size=config.hidden_size, output_size=1, config=config)

        return model

    return model_provider


def wrap_model_provider_with_freeze(original_provider, args):
    def wrapped_provider(
        pre_process=True,
        post_process=True,
        **kwargs,
    ):
        sig = inspect.signature(original_provider)
        provider_kwargs = {
            "pre_process": pre_process,
            "post_process": post_process,
        }
        for key in ["vp_stage", "config", "pg_collection"]:
            if key in sig.parameters:
                provider_kwargs[key] = kwargs.get(key, None)

        model = original_provider(**provider_kwargs)
        freeze_model_params(model, args)

        return model

    return wrapped_provider


def get_model_provider_func(args, role="actor"):
    return wrap_model_provider_with_freeze(_get_model_provider_func(args, role), args)


def freeze_model_params(model: GPTModel, args: argparse.Namespace):
    if getattr(args, "only_train_params_name_list", None):
        for name, param in model.named_parameters():
            param.requires_grad = False
            for pattern in args.only_train_params_name_list:
                if re.search(pattern, name):
                    param.requires_grad = True
                    break

    if getattr(args, "freeze_params_name_list", None):
        for name, param in model.named_parameters():
            for pattern in args.freeze_params_name_list:
                if re.search(pattern, name):
                    param.requires_grad = False
                    break

    if getattr(args, "freeze_indexer", False):
        frozen_indexer_params = []
        has_self_attention_params = False
        for name, param in model.named_parameters():
            has_self_attention_params |= "self_attention" in name.split(".")
            if _is_indexer_parameter(name):
                param.requires_grad = False
                frozen_indexer_params.append(name)

        if has_self_attention_params and not frozen_indexer_params:
            raise RuntimeError(
                "--freeze-indexer was requested, but this model chunk has self-attention "
                "parameters and no recognized DSA indexer parameters."
            )

        # Some pipeline stages may legitimately own no indexer weights, so an
        # empty local tuple is not itself an error.
        model._slime_frozen_indexer_param_names = tuple(frozen_indexer_params)

