def create_actor_model(args, pgs, rollout_manager, actor_cls=None):
    actor_args = args
    if args.megatron_config_path is not None:
        from slime.utils.arguments import parse_megatron_role_args

        actor_args = parse_megatron_role_args(args, args.megatron_config_path, role="actor")

    actor_model_kwargs = {}
    if actor_cls is not None:
        actor_model_kwargs["actor_cls"] = actor_cls
    actor_model = allocate_train_group(
        args=actor_args,
        num_nodes=args.actor_num_nodes,
        num_gpus_per_node=args.actor_num_gpus_per_node,
        pg=pgs["actor"],
        with_ref=actor_args.kl_coef != 0 or actor_args.use_kl_loss,
        with_opd_teacher=actor_args.use_opd and actor_args.opd_type == "megatron",
        **actor_model_kwargs,
    )
    actor_start_rollout_ids = actor_model.create(rollout_manager=rollout_manager)
    return actor_model, actor_start_rollout_ids


def create_training_models(args, pgs, rollout_manager, actor_cls=None):
    actor_model, actor_start_rollout_ids = create_actor_model(args, pgs, rollout_manager, actor_cls=actor_cls)

    critic_model = None
    if args.use_critic and args.num_rollout != 0:
        from slime.utils.arguments import parse_megatron_role_args

        critic_args = (
            parse_megatron_role_args(args, args.megatron_config_path, role="critic")
            if args.megatron_config_path is not None
            else copy.deepcopy(args)
        )
        if args.megatron_config_path is None:
            critic_args.disable_param_buffers_cpu_backup = False

        critic_model = allocate_train_group(
            args=critic_args,
            num_nodes=args.critic_num_nodes,
            num_gpus_per_node=args.critic_num_gpus_per_node,
            pg=pgs["critic"],
            role="critic",
        )
        critic_start_rollout_ids = critic_model.create(rollout_manager=rollout_manager)

    # TODO how to decide rollout start id when critic is involved? For now we just require user to specify it via args.
    if critic_model is not None:
        start_rollout_ids = critic_start_rollout_ids
    else:
        start_rollout_ids = actor_start_rollout_ids

    assert len(set(start_rollout_ids)) == 1

    if args.start_rollout_id is None:
        args.start_rollout_id = start_rollout_ids[0]

    if args.rollout_global_dataset:
        ray.get(rollout_manager.load.remote(args.start_rollout_id - 1))

    return actor_model, critic_model


def create_rollout_manager(args, pg):
    from .rollout import RolloutManager

    rollout_manager_options = {
        "num_cpus": 1,
        "num_gpus": 0,
        "runtime_env": {"env_vars": add_default_ray_env_vars()},
    }
    if getattr(args, "rollout_data_transport", "object-store") == "nixl":
        rollout_manager_options["enable_tensor_transport"] = True
    rollout_manager = RolloutManager.options(**rollout_manager_options).remote(args, pg)

    # calculate num_rollout from num_epoch
    num_rollout_per_epoch = None
    if args.num_rollout is None:
        num_rollout_per_epoch = ray.get(rollout_manager.get_num_rollout_per_epoch.remote())
        args.num_rollout = num_rollout_per_epoch * args.num_epoch
        assert args.num_rollout > 0

    if args.check_weight_update_equal:
        ray.get(rollout_manager.check_weights.remote(action="snapshot"))
        ray.get(rollout_manager.check_weights.remote(action="reset_tensors"))

    if args.offload_rollout:
        ray.get(rollout_manager.offload.remote())

    return rollout_manager, num_rollout_per_epoch

def save_model(self, rollout_id, force_sync=False):
    """Save actor model"""
    ret = ray.get([actor.save_model.remote(rollout_id, force_sync=force_sync) for actor in self._actor_handlers])
    if self._release_train_enabled():
        self.args.load = self.args.save
        self.args.ckpt_step = None
        self.args.finetune = False
        self.args.no_load_optim = self.args.no_save_optim
        self.args.no_load_rng = False
    return ret

def update_weights(self):
    """Broadcast weights from rank 0 to all other ranks."""
    if not self._full_disk_weight_update_enabled():
        return ray.get([actor.update_weights.remote() for actor in self._actor_handlers])

    weight_version = self._disk_weight_version + 1
    disk_weight_dir = Path(self.args.update_weight_disk_dir) / f"weight_v{weight_version:06d}"
    ray.get([actor.update_weights.remote() for actor in self._actor_handlers])
    self._disk_weight_version = weight_version
    if self._release_train_enabled():
        self.release()
    self._reload_rollout_weights_from_disk(disk_weight_dir, str(weight_version))

def onload(self):
    return ray.get([actor.wake_up.remote() for actor in self._actor_handlers])

def offload(self):
    return ray.get([actor.sleep.remote() for actor in self._actor_handlers])

def release(self):
    actors, self._actor_handlers = self._actor_handlers, []
    for actor in actors:
        ray.kill(actor, no_restart=True)
    if actors:
        time.sleep(5)

def create(self, rollout_manager=None):
    if self._actor_handlers:
        return None
    if rollout_manager is not None:
        self._rollout_manager = rollout_manager
    self.args.update_weight_start_version = self._disk_weight_version
    self._allocate_gpus_for_actor(self._pg, self._num_gpus_per_actor)
    start_rollout_ids = ray.get(
        [
            actor.init.remote(
                self.args,
                self.role,
                with_ref=self._with_ref,
                with_opd_teacher=self._with_opd_teacher,
            )
            for actor in self._actor_handlers
        ]
    )
    if self._rollout_manager is not None:
        self.set_rollout_manager(self._rollout_manager)
    return start_rollout_ids

def clear_memory(self):
    return ray.get([actor.clear_memory.remote() for actor in self._actor_handlers])

def set_rollout_manager(self, rollout_manager):
    self._rollout_manager = rollout_manager
    return ray.get([actor.set_rollout_manager.remote(rollout_manager) for actor in self._actor_handlers])

def _release_train_enabled(self):
    return self.role == "actor" and getattr(self.args, "release_train", False)

def _full_disk_weight_update_enabled(self):
    return (
        self.role == "actor"
        and self.args.update_weight_mode == "full"
        and self.args.update_weight_transport == "disk"
    )

def _reload_rollout_weights_from_disk(self, disk_weight_dir, weight_version):
    assert self._rollout_manager is not None, "disk weight update requires a rollout manager."
    if self.args.offload_rollout:
        ray.get(self._rollout_manager.onload_weights.remote())
    engines, *_ = ray.get(self._rollout_manager.get_updatable_engines_and_lock.remote())
    if not engines:
        if not self.args.update_weight_disk_keep_files:
            shutil.rmtree(disk_weight_dir, ignore_errors=True)
        return
    if self.args.update_weight_local_checkpoint_dir:
        # each host pulls the published checkpoint onto local disk (e.g. NVMe) and
        # the engines reload from there; the pull is disk-only, so it runs before
        # pause and overlaps generation
        ray.get([engine.pull_weights.remote(int(weight_version)) for engine in engines])
        model_path = self.args.update_weight_local_checkpoint_dir
    else:
        model_path = str(disk_weight_dir)
    ray.get([engine.pause_generation.remote() for engine in engines])
    ray.get([engine.flush_cache.remote() for engine in engines])
    ray.get(
        [
            engine.update_weights_from_disk.remote(
                model_path=model_path,
                weight_version=weight_version,
            )
            for engine in engines
        ]
    )
    if self.args.ci_test:
        engine_versions = ray.get([engine.get_weight_version.remote() for engine in engines])
        mismatches = [
            f"engine {idx}: {engine_version}"
            for idx, engine_version in enumerate(engine_versions)
            if str(engine_version) != str(weight_version)
        ]
        if mismatches:
            raise RuntimeError(
                "Weight version mismatch after disk reload! "
                f"Expected: {weight_version}; " + ", ".join(mismatches)
            )
    if not self.args.update_weight_disk_keep_files:
        shutil.rmtree(disk_weight_dir, ignore_errors=True)
    ray.get([engine.continue_generation.remote() for engine in engines])

    if not args.debug_rollout_only:
        megatron_validate_args(args)

    if not args.debug_train_only:
        sglang_validate_args(args)

    return args


def _apply_megatron_role_overrides(base_args, overrides, role):
    role_args = copy.deepcopy(base_args)
    ignored_keys = {"num_nodes", "num_gpus_per_node"}

    # Apply overrides from the YAML config.
    # Unspecified keys inherit from base_args via deepcopy.
    for key, value in overrides.items():
        if key in ignored_keys:
            logger.info(f"Ignoring {role} config key '{key}'; GPU allocation always follows CLI args.")
            continue
        if not hasattr(role_args, key):
            logger.warning(f"{role.capitalize()} config key '{key}' is not a known argument, setting it anyway.")
        else:
            # YAML safe_load doesn't parse scientific notation (e.g. 1e-5) as float.
            # Coerce the value to match the type of the existing attribute.
            original = getattr(role_args, key)
            if original is not None and isinstance(value, str) and isinstance(original, (int, float)):
                try:
                    value = type(original)(value)
                except (ValueError, TypeError):
                    pass
        setattr(role_args, key, value)

    if role == "critic":
        # Critic-specific: disable features that only apply to actors.
        role_args.kl_coef = 0
        role_args.use_opd = False
        role_args.custom_advantage_function_path = None
        role_args.untie_embeddings_and_output_weights = True
        if "disable_param_buffers_cpu_backup" not in overrides:
            role_args.disable_param_buffers_cpu_backup = False

    return role_args


def parse_megatron_role_args(base_args, megatron_config_path, role):
    """Parse role-specific arguments from a unified Megatron YAML config.

    The config must contain a top-level ``megatron`` list with per-role entries.
    Missing roles inherit the base args unchanged.
    """
    assert role in {"actor", "critic"}, f"Unsupported Megatron config role: {role}"

    with open(megatron_config_path) as f:
        raw_config = yaml.safe_load(f) or {}

    assert "megatron" in raw_config, (
        "megatron config must contain a top-level 'megatron' list, e.g. "
        "megatron: [{name: default, role: actor, overrides: {...}}]"
    )

    overrides = {}
    megatron_entries = raw_config["megatron"]
    assert isinstance(megatron_entries, list), (
        "megatron config 'megatron' field must be a list, e.g. "
        "megatron: [{name: default, role: actor, overrides: {...}}]"
    )
    role_entries = [entry for entry in megatron_entries if entry.get("role") == role]
    assert len(role_entries) <= 1, (
        f"megatron config must contain at most one entry with role={role}, e.g. "
        f"megatron: [{{name: default, role: {role}, overrides: {{...}}}}]"
    )
    if role_entries:
        role_entry = role_entries[0]
        overrides = role_entry.get("overrides") or role_entry.get("args") or {}
    else:
        logger.info(
            f"No megatron config entry with role={role} found in {megatron_config_path}; using inherited args."
        )

    role_args = _apply_megatron_role_overrides(base_args, overrides, role)
    logger.info(
        f"Parsed megatron config for role={role} from {megatron_config_path}: overrides = {list(overrides.keys())}"
    )

    return role_args


def _resolve_eval_datasets(args) -> list[EvalDatasetConfig]:
    """
    Build evaluation dataset configurations from either --eval-config or --eval-prompt-data.
    """
    datasets_config = []
    defaults: dict[str, Any] = {}

    if args.eval_config:
        from omegaconf import OmegaConf

        cfg = OmegaConf.load(args.eval_config)
        cfg_dict = OmegaConf.to_container(cfg, resolve=True)
        if not isinstance(cfg_dict, dict):
            raise ValueError("--eval-config must contain a mapping at the root.")

        eval_cfg = cfg_dict.get("eval", cfg_dict)
        if not isinstance(eval_cfg, dict):
            raise ValueError("--eval-config must define an `eval` mapping or be a mapping itself.")

        defaults = dict(eval_cfg.get("defaults") or {})
        datasets_config = ensure_dataset_list(eval_cfg.get("datasets"))
        if not datasets_config:
            raise ValueError("--eval-config does not define any datasets under `eval.datasets`.")
    elif args.eval_prompt_data:
        values = list(args.eval_prompt_data)
        if len(values) == 1:
            logger.info("[legacy] only one eval_prompt_data detected, will assume it is data for aime")
            values = ["aime", values[0]]
        if len(values) % 2 != 0:
            raise ValueError("eval prompt data must be provided as name/path pairs.")
        datasets_config = [{"name": values[i], "path": values[i + 1]} for i in range(0, len(values), 2)]
    else:
        datasets_config = []

    eval_datasets = build_eval_dataset_configs(args, datasets_config, defaults)
    if eval_datasets:
        args.eval_prompt_data = [item for dataset in eval_datasets for item in (dataset.name, dataset.path)]
    else:
        args.eval_prompt_data = None

    return eval_datasets


